"""Author transcription after reading/viewing all 10 main and 9 SI pages; audit pending."""
FACTS=[]
TITLE='New Insights into the Complexities of Shell Growth and the Strong Influence of Particle Volume in Nonblinking “Giant” Core/Shell Nanocrystal Quantum Dots'
AUTHORS=['Yagnaseni Ghosh','Benjamin D. Mangum','Joanna L. Casson','Darrick J. Williams','Han Htoon','Jennifer A. Hollingsworth']
def F(i,role,p,loc,title,claim,scope,qs=(),flags=(),kind='reported_source_evidence'):
 FACTS.append((i,role,p,loc,title,claim,scope,list(qs),list(flags),kind))
def Q(name,raw,unit):return(name,raw,unit)
F('materials','main',2,'Materials','Reported reagent grades','Aldrich CdO, oleic acid, ODE, OD, oleylamine, sulfur, selenium and TOP were used as received; Strem TOPO was also used as received. OD is literally called 1-octadecane. Oleylamine is technical grade; dioctylamine grade and supplier are not supplied.','reagents',[Q('CdO purity','99.95','%'),Q('oleic acid purity','90','%'),Q('ODE purity','90','%'),Q('OD purity','90','%'),Q('sulfur purity','99.98','%'),Q('selenium purity','>=99.999','%'),Q('TOP purity','97','%'),Q('TOPO purity','90','%')],['G1'])
F('core-charge','main',3,'Optimized Synthetic Protocol / CdSe Core Synthesis','Core initial charge','Charge TOPO, ODE and Cd-oleate into a round-bottom flask with reflux condenser and thermocouple, under standard air-free conditions. The source cites reference 4 for a modified parent method; that reference has not been read.','core-common',[Q('flask volume','100','mL'),Q('TOPO mass','1','g'),Q('ODE volume','8','mL'),Q('Cd-oleate amount','0.38','mmol')],['G1'])
F('core-degas','main',3,'CdSe Core Synthesis','Core evacuation and heating','Evacuate first at room temperature, then at 80 °C, and heat under argon before rapid injection.','core-common',[Q('room-temperature evacuation duration','30','min'),Q('heated evacuation duration','30','min'),Q('heated evacuation temperature','80','degC'),Q('pre-injection temperature','300','degC')],['G2'])
F('core-inject','main',3,'CdSe Core Synthesis','Selenium injection','Quickly inject TOP-Se with oleylamine and ODE; lower the temperature for growth. TOP-Se preparation and final mixture volume are not specified.','core-common',[Q('TOP-Se amount','4','mmol'),Q('oleylamine volume','3','mL'),Q('ODE injection volume','1','mL'),Q('growth temperature','270','degC')],['G1','G2'])
F('core-standard','main',3,'CdSe Core Synthesis','Standard 3 or 4 nm cores','After several minutes, cool to room temperature and collect by ethanol precipitation and centrifugation. Exact time distinguishing 3 from 4 nm is not supplied.','core-3-or-4',[Q('reported core diameter option 1','3','nm'),Q('reported core diameter option 2','4','nm'),Q('growth duration','several minutes','min')],['G2','G3'])
F('core-wash','main',3,'CdSe Core Synthesis','Core purification','Redisperse collected cores in hexane after two to three precipitation/collection cycles. Ethanol and hexane quantities and centrifugation conditions are absent.','core-common',[Q('precipitation collection cycles','2-3','count')],['G2'])
F('core-small','main',3,'CdSe Core Synthesis','Small-core quench variant','To obtain 2.2 nm cores, add cold toluene several seconds after selenium injection. Neither toluene temperature nor volume is given.','core-2p2',[Q('core diameter','2.2','nm'),Q('quench delay','several seconds','s')],['G2'])
F('core-large','main',3,'CdSe Core Synthesis','Large-core feeding variant','After initial growth, add additional Cd-oleate and TOP-Se dropwise at 270 °C, then grow at 300 °C.','core-5p5',[Q('core diameter','5.5','nm'),Q('initial growth time','~10','min'),Q('additional Cd-oleate','0.8','mmol'),Q('additional TOP-Se','8','mmol'),Q('feed temperature','270','degC'),Q('additional growth duration','10','min'),Q('additional growth temperature','300','degC')],['G2'])
F('shell-charge','main',3,'CdSe/nCdS Core–Shell g-NQD Synthesis','Optimized shell charge','Use washed CdSe cores, oleylamine and OD in a round-bottom flask. OD was selected to alleviate late-stage precipitation.','optimized-shell',[Q('flask volume','250','mL'),Q('washed core amount','~2e-7','mol'),Q('oleylamine volume','5','mL'),Q('OD volume','5','mL')],['G3'])
F('shell-stocks','main',3,'CdSe/nCdS Core–Shell g-NQD Synthesis','Shell precursor stocks','Elemental sulfur and Cd-oleate stocks are in OD. Stock preparation details, stock volume and per-layer delivered volumes are not supplied.','optimized-shell',[Q('sulfur stock concentration','0.2','mol/L'),Q('Cd-oleate stock concentration','0.2','mol/L')],['G1','G4'])
F('shell-passivation','main',3,'CdSe/nCdS Core–Shell g-NQD Synthesis','Core surface prepassivation','Before SILAR, add Cd-oleate equivalent to one Cd monolayer to Se-rich core surfaces. The source does not report a measured surface stoichiometry.','optimized-shell',[Q('Cd passivation equivalent','1','monolayer')],['G4'])
F('shell-ligand-switch','main',3,'CdSe/nCdS Core–Shell g-NQD Synthesis','Shell-stock ligand ratio switch','For the first 5–8 shell deposition cycles use Cd:oleic acid 1:4; use 1:10 for each succeeding layer. The exact switch cycle is not fixed.','optimized-shell',[Q('initial cycle span','5-8','monolayer'),Q('initial Cd:OA','1:4','ratio_parts'),Q('later Cd:OA','1:10','ratio_parts')],['C1','G4'])
F('shell-anneal','main',3,'CdSe/nCdS Core–Shell g-NQD Synthesis','Optimized annealing','Grow at 240 °C, waiting one hour after sulfur and 2.5 hours after cadmium, until the desired shell thickness. This preferred protocol is separate from Table 1 comparison schedules.','optimized-shell',[Q('shell-growth temperature','240','degC'),Q('post-sulfur anneal','1','h'),Q('post-cadmium anneal','2.5','h')],['C1','G4'])
F('shell-withdraw','main',3,'CdSe/nCdS Core–Shell g-NQD Synthesis','Progressive precursor excess','Withdraw 1% of the total reaction solution after each completed monolayer, without reducing subsequent precursor quantities for the remaining dots. The percentage denotes removed reaction volume, not a fixed precursor molar excess.','optimized-shell',[Q('withdrawn reaction volume fraction','1','%')],['G4'])
F('shell-wash-qy','main',3,'CdSe/nCdS Core–Shell g-NQD Synthesis','Shell purification and relative QY','Wash by ethanol precipitation and hexane redispersion two to three times. Relative emission QYs are measured against Rhodamine 6G from Acros; unspecified optical matching and purification conditions remain gaps.','optimized-shell',[Q('precipitation cycles','2-3','count'),Q('Rhodamine 6G purity','99','%')],['G2','G5'])
F('ml-model','main',6,'Impact of Reaction Stoichiometry','Monolayer accounting model','Estimate required shell material from core concentration, core size and successive shell volume increments, assuming complete precursor conversion and one monolayer equal to half the wurtzite c parameter. These assumptions do not constitute measured lattice constants or atomic coordinates.','author-ml-accounting',[Q('assumed conversion','100','%'),Q('assumed monolayer thickness','0.3375','nm')],['G4','G6'],kind='author_model')
F('thin-shell-baseline','main',3,'Results and Discussion','Thin-shell baseline','Washed cores typically have 15–20% emission QY; thin CdS shells give a three- to four-fold improvement largely independent of annealing time. Thin-shell discussion refers approximately to one to three monolayers.','thin-shell-context',[Q('typical core QY','15-20','%'),Q('thin-shell enhancement','3-4','fold'),Q('thin-shell thickness','~1-3','monolayer'),Q('minimum core washing steps','>=2','count')],['G3'])
F('short-anneal-tem','si',2,'Figure S1','Short-anneal size series','Ten-minute anneals after each cation/anion addition produce the displayed TEM size series; the source describes reasonable agreement with its monolayer-size calculation. The starting core diameter is not separately identified in this caption.','short-anneal-series',[Q('post-cation time','10','min'),Q('post-anion time','10','min'),Q('S1a shell count','5','monolayer'),Q('S1a overall diameter','8.29','nm'),Q('S1b shell count','11','monolayer'),Q('S1b overall diameter','12.01','nm'),Q('S1c shell count','19','monolayer'),Q('S1c overall diameter','17.3','nm'),Q('all panel scale bars','10','nm')],['G3'])
F('anneal-qy-summary','main',4,'Impact of Anneal Times','Numerical anneal comparison','At five monolayers, the text reports 21±0.2% for a 20-minute total anneal and 41±6% for a stated three-hour total, averaged over different relative cation/anion times. Preserve these summary statistics separately from Table 1 approximations and schedules.','anneal-comparison',[Q('short total anneal','20','min'),Q('five-ML short-anneal QY','21±0.2','%'),Q('stated long total anneal','3','h'),Q('five-ML long-anneal QY','41±6','%'),Q('shell thickness','5','monolayer')],['C2'])
F('anneal-asymmetry','main',4,'Impact of Anneal Times','Asymmetric anneal result','Longer annealing after Cd addition performs better than the reverse at equal nominal short/long conditions; Table 1 contains the complete five-schedule values. Longer total anneals do not remove all batch variability.','anneal-comparison',[Q('long post-Cd interval','~3','h'),Q('short post-S interval','10','min'),Q('post-Cd-long five-ML QY','>45','%'),Q('post-S-long five-ML QY','~35','%')],['C2'])
F('historical-qy','main',4,'Impact of Anneal Times','Historical thick-shell QY variability','The article describes prior protocols as yielding QYs as high as 40% but regularly no more than 25% across thick shells; these are historical context, not exact measurements for the present table rows.','cited-prior-gNQD',[Q('historical thick-shell span','11-20','monolayer'),Q('historical upper QY','40','%'),Q('regular historical QY','<=25','%')],['G3'],kind='cited_context')
F('ode-cycling','main',4,'Impact of Reaction Homogeneity','ODE precipitation cycling','For 3–4 nm cores in ODE/primary amine, precipitation begins after about seven monolayers following Cd addition. Added S/ODE initially redissolves particles; at more than eleven layers an entire sulfur aliquot no longer fully clears the solution.','ode-primary',[Q('core diameter span','3-4','nm'),Q('precipitation onset','~7','monolayer'),Q('incomplete clearing beyond','>11','monolayer')],['G3'])
F('od-cycling','main',5,'Impact of Reaction Homogeneity','OD substitution','Replacing ODE by OD delays initial turbidity until at least eleven monolayers.','od-primary',[Q('OD turbidity onset','>=11','monolayer')],['G3'])
F('od-late-dilution','main',5,'Impact of Reaction Homogeneity','Late modest dilution','Beginning at ten monolayers, modest OD dilution reduces dot concentration and improves size/shape uniformity. Combined with longer annealing, this produces the Table 2 row 3 spherical/faceted population; no complete per-layer dilution schedule is given.','od-late-dilution',[Q('dilution starting shell count','10','monolayer'),Q('initial dot concentration','9e-6','mol/L'),Q('diluted dot concentration','7e-6','mol/L')],['G3','G4'])
F('extreme-dilution','main',5,'Impact of Reaction Homogeneity','Extreme dilution negative outcome','Extreme initial dilution abolishes turbidity but yields half-moon particles, polytypic structure and low QYs at all shell thicknesses.','od-extreme-dilution',[Q('initial dot concentration','1.5e-6','mol/L'),Q('QY all shell thicknesses','<15','%')],['G3'])
F('ligand-amounts','main',5,'Impact of Coordinating Ligands','Ligand composition context','The described typical shell reaction adds all primary oleylamine initially, while OA enters with each Cd aliquot. An illustrative fourteen-layer context compares 15 mmol amine with 6.5 mmol OA. The medium is approximately equal polar/nonpolar mass; this is not a complete formulation recipe.','ligand-series',[Q('initial amine','15','mmol'),Q('OA after fourteen layers','6.5','mmol'),Q('associated shell count','14','monolayer'),Q('Cd:OA option 1','1:4','ratio_parts'),Q('Cd:OA option 2','1:10','ratio_parts')],['G3','G4'])
F('ftir-primary-low-oa','main',5,'Figure 1a,d and discussion','Mixed surface signature','Primary amine with Cd:OA 1:4 gives both amine and oleate FTIR signatures. Assignments concern surface functional groups, not a quantitatively measured ligand coverage.','ftir-primary-1to4',[Q('Cd:OA ratio','1:4','ratio_parts'),Q('amine NH2 bending','~1635','cm^-1'),Q('oleate asymmetric stretch','1555','cm^-1'),Q('oleate symmetric stretch','1408','cm^-1')],['G7'])
F('ftir-high-oa','main',5,'Figure 1b,e and discussion','Oleate-dominated primary-amine preparation','At Cd:OA 1:10, the source describes exclusively oleate capping and more faceted particles. Acid-like C=O near 1710 cm−1 is rarely observed in these particle studies.','ftir-primary-1to10',[Q('Cd:OA ratio','1:10','ratio_parts'),Q('acid-like C=O','~1710','cm^-1')],['G7'])
F('ftir-secondary','main',5,'Figure 1c,f','Secondary-amine thick-shell FTIR','Dioctylamine with Cd:OA 1:4 gives exclusively oleate signatures in the thick-shell comparison. This is distinct from the thin-shell SI S6 wording conflict.','ftir-secondary-thick',[Q('Cd:OA ratio','1:4','ratio_parts')],['C3','G7'])
F('secondary-shape','main',6,'Coordinating ligand discussion','Dioctylamine outcome','Dioctylamine suppresses precipitation but gives nonemissive octahedral particles with predominantly wurtzite phase. The proposed eight alternating polar facets and nonpolar overall shape are the authors’ interpretation, not an atomic-coordinate reconstruction.','od-secondary',[Q('interpreted octahedron face count','8','count'),Q('upper face count','4','count'),Q('lower face count','4','count')],['G6','G7'])
F('steric-model','main',6,'Coordinating ligand discussion / Figure S5','Ligand steric interpretation','The authors speculate that the secondary amine functions as a base but is disfavored as a thick-shell bound ligand by steric crowding. Surface flattening favors oleate. Figure S5 is a conceptual packing drawing; its branched descriptor refers to the secondary-amine architecture, not an identified carbon-chain isomer.','author-ligand-packing',[],['G7'],kind='author_interpretation')
F('no-added-amine','main',6,'Coordinating ligand discussion','No-added-amine variant','Removing added amine, while allowing residual core-bound primary amine, causes the earliest precipitation from three monolayers. Table 2 separately places hexagonal faceting beyond six monolayers.','od-no-added-amine',[Q('precipitation onset','3','monolayer'),Q('faceting shell count','>6','monolayer')],['G3','G7'])
F('withdrawal-series','main',6,'Impact of Reaction Stoichiometry','Aliquot-withdrawal comparison','Withdraw 1% or 10% after each complete shell cycle but retain the original precursor doses. Both reduce precipitation; the larger withdrawal almost eliminates it but gives poor QY and misshapen particles. Lesser withdrawal gives rods or irregular particles.','withdrawal-series',[Q('small withdrawal','1','%'),Q('large withdrawal','10','%'),Q('large-withdrawal QY','<10','%'),Q('small-withdrawal QY','35-40','%')],['G3','G4'])
F('withdrawal-oa','main',6,'Impact of Reaction Stoichiometry','Withdrawal plus OA optimization','Combine 1% withdrawals with 2.5-fold more OA per layer starting at the fifth to eighth shell. Thick-shell QY reaches 50% with symmetric spherical/hexagonal particles, while precipitation returns. Do not replace the experimental paragraph’s switch wording with a single exact cycle.','withdrawal-oa',[Q('withdrawal','1','%'),Q('OA factor','2.5','fold'),Q('OA change shell span','5-8','monolayer'),Q('reported QY','50','%')],['C1','G4'])
F('constant-s-protocol','main',6,'Impact of Reaction Stoichiometry final paragraph','All-sulfur-at-start variant','Charge sulfur sufficient for thirteen monolayers at the start, then add only Cd precursor one monolayer at a time with four-hour intervals. This is a distinct modified SILAR schedule.','constant-s',[Q('sulfur total equivalent','13','monolayer'),Q('between-Cd anneal','4','h')],['G4'])
F('constant-s-outcome','main',7,'Impact of Reaction Stoichiometry continuation','Constant-sulfur negative outcome','Turbidity begins at seven layers but remains approximately constant and smaller rather than cycling. QY is low, particles are rods, and XRD gives wurtzite:zinc-blende 40:60.','constant-s',[Q('turbidity onset','7','monolayer'),Q('WZ:ZB ratio','40:60','weight_ratio_parts')],['G3','G6'])
F('attachment-image','main',7,'Figure 2','Connected particles','TEM shows connected CdSe/CdS particles outlined by the authors in red. They interpret the attachments as consistent with dipole-driven association; the image alone does not measure dipole magnitude or establish all solution-state associations.','attached-particle-context',[Q('scale bar','5','nm')],['G3','G6'])
F('dipole-model','main',7,'Solubility Cycling: Mechanism and Significance','Dipole-driven cycling proposal','The authors hypothesize increasing dipoles as wurtzite/hexagonal particles grow, transient c-axis association and occasional permanent fusion. Surface-charge mechanisms from prior literature remain an alternative discussion. No dipole values are measured here.','author-dipole-model',[],['G6'],kind='author_interpretation')
F('termination-model','main',8,'Solubility Cycling continuation','Termination and reconstruction proposal','Cd-binding ligands are proposed to stabilize Cd-terminated wurtzite surfaces; sulfur addition is proposed to reconstruct surfaces and reduce dipole strength. The source says cycling behavior does not depend on whether Cd or S begins the shell sequence. The generic Scheme 1 starts with anion, whereas the preferred protocol first prepassivates cores with Cd.','author-termination-model',[],['G6','G7'],kind='author_interpretation')
F('optimized-performance','main',8,'Larger Core Sizes discussion','Optimized thick-shell performance','The preferred method consistently gives emission QY above 50% for shells thicker than fifteen monolayers, with improved size/shape uniformity. This population-level statement does not assign a QY to every lifetime-table row.','optimized-performance',[Q('thick-shell QY','>50','%'),Q('thick-shell span','>15','monolayer')],['G3'])
F('core-series','main',8,'Figure 3a','Four-core blinking comparison','Black, red, green and blue data correspond to 2.2, 3.0, 4.0 and 5.5 nm initial cores. Nonblinking fractions increase with shell thickness but the onset differs by core size. Dotted trends are not exact numeric datasets.','four-core-series',[Q('black core diameter','2.2','nm'),Q('red core diameter','3.0','nm'),Q('green core diameter','4.0','nm'),Q('blue core diameter','5.5','nm')],['G3','G8'])
F('nonblinking-definition','main',4,'Anneal discussion / Figure 3 definition','Nonblinking definition','Main prose uses greater than 99% on-time over sixty minutes, while Figure 3 uses at least 99%. Retain the printed inequality distinction; denominator is dots that emitted at least once during observation.','blinking-analysis',[Q('prose on-time threshold','>99','%'),Q('prose observation duration','60','min')],['C4'])
F('nonblinking-large','main',8,'Figure 3b and discussion','Large-core blinking suppression','Extra-large-core thick-shell particles exceed 85% nonblinking population, while the smallest cores retain little nonblinking behavior even at ultra-thick shells. This is a sampled fraction and not a claim that every particle is nonblinking.','four-core-series',[Q('large-core nonblinking fraction','>85','%'),Q('Figure 3 on-time threshold','>=99','%')],['C4','G8'])
F('volume-threshold','main',9,'Figure 3c discussion','Empirical volume relationship','Across the measured series, the authors describe an approximate minimum volume near 750 nm³ and roughly linear growth of the nonblinking fraction above it. This is a paper-specific empirical trend, not a universal threshold or a predictive training label.','four-core-series',[Q('approximate threshold volume','~750','nm^3')],['G3','G8'])
F('lifetime-volume','main',9,'Figure 4 and discussion','Lifetime-volume relation','Below approximately 750 nm³ the lifetimes span approximately 20–50 ns; most core series approach a roughly 65 ns plateau above it. The 3.0 nm core series is an explicit exception and continues increasing. Preserve all Table S1 values.','four-core-series',[Q('threshold volume','~750','nm^3'),Q('below-threshold lifetime span','~20-50','ns'),Q('plateau lifetime','~65','ns'),Q('exception core diameter','3.0','nm'),Q('discussed core-only/thin-shell lifetime','20-30','ns')],['G8'])
F('quasi-type-ii','main',9,'Lifetime discussion and Conclusion','Electronic-structure interpretation','Longer lifetimes are attributed to quasi-type-II alignment, with core-localized holes and electrons extending into the shell; Coulomb interactions are proposed to limit electron delocalization. No new band-offset calculation, measured wavefunction, or product coordinates are supplied.','author-electronic-model',[],['G6'],kind='author_interpretation')
F('ensemble-acquisition','main',2,'General Methods','Ensemble spectroscopy','Absorption uses CARY UV-Vis-NIR and emission Horiba NanoLog. No full wavelength program or per-sample concentration is given.','characterization',[],['G5'])
F('ftir-acquisition','main',2,'General Methods','FTIR preparation and acquisition','Rigorously purify particle dispersions through six precipitation/resuspension cycles, drop on a diamond ATR cell, evaporate solvent and acquire using Nicolet 6700. Pure OA, oleylamine, dioctylamine, TOP and TOPO are cast from hexane/surfactant mixtures for comparison.','ftir-acquisition',[Q('washing cycles','6','count'),Q('spectral resolution','4','cm^-1'),Q('accumulated scans','32','count')],['G2','G5'])
F('tem-acquisition','main',2,'General Methods','TEM acquisition','A JEOL 2010 TEM provides images. Operating voltage, grid, deposition protocol and particle-count distribution statistics are not specified.','tem-acquisition',[],['G5'])
F('xrd-acquisition','main',2,'General Methods','Powder XRD acquisition','Deposit on a background-less silicon slide and acquire Rigaku Ultima III Cu Kα diffraction in continuous scan mode with parallel-beam slit geometry.','xrd-acquisition',[Q('Cu Kalpha wavelength','1.5406','angstrom'),Q('2theta scan interval','10-90','deg'),Q('sampling width','0.005','deg'),Q('scan speed','0.100','deg/min')],['G6'])
F('xrd-phase-fit','si',4,'Figure S4 continued caption','Semiquantitative phase analysis','Jade 9.0 Whole Pattern Fitting/Rietveld fits unit-cell constants, background and profile parameters to estimate relative phase weight percentages. Actual refined unit-cell constants or coordinates are not supplied.','xrd-acquisition',[],['G6'])
F('xrd-pattern-values','si',3,'Figure S4b–d','Displayed XRD phase ratios','The plotted primary-amine, secondary-amine and constant-sulfur traces are labeled W:ZB 74:26, 67:33 and 40:60. The secondary-amine Table 2 value is approximate 70:30; do not silently replace the exact plot label.','xrd-three-contexts',[Q('S4b primary-amine WZ:ZB','74:26','weight_ratio_parts'),Q('S4c secondary-amine WZ:ZB','67:33','weight_ratio_parts'),Q('S4d constant-sulfur WZ:ZB','40:60','weight_ratio_parts')],['C5','G3','G6'])
F('single-dot-preparation','main',2,'Single-NQD Imaging','Single-dot deposition','Dilute hexane dispersions until individual dots resolve, then drop-cast on acetone-cleaned glass coverslips. Numerical dilution and deposited volume are absent.','single-dot-acquisition',[],['G5'])
F('single-dot-excitation','main',2,'Single-NQD Imaging','Single-dot illumination','A Coherent Cube continuous-wave diode at 405 nm illuminates the sample. A simple lens gives an approximately circular focal spot. PL passes through a dichroic and spectral filter to a liquid-nitrogen-cooled Princeton Spec-10 CCD.','single-dot-acquisition',[Q('excitation wavelength','405','nm'),Q('average optical power','~15','mW'),Q('spot diameter','~75','um')],['G5'])
F('single-dot-frames','main',2,'Single-NQD Imaging','Single-dot time series','Collect 20,000 frames with 100 ms integration and approximately 90 ms readout while constantly illuminated, giving slightly more than one hour total. SI S8 reports readout as 91 ms.','single-dot-acquisition',[Q('frame count','20000','count'),Q('integration time','100','ms'),Q('main readout delay','~90','ms'),Q('total measurement time','>1','h')],['G5'])
F('single-dot-analysis','main',2,'Single-NQD Imaging equation','Blinking analysis','Igor Pro groups pixels into dots, averages pixel intensity per dot and frame, and applies I_pix > BG + 2 sqrt(BG). I_pix is not background-subtracted. Below-threshold dots may remain discernible. Statistics use all dots that ever emitted, not every physical deposited particle.','single-dot-analysis',[],['C4'])
F('lifetime-preparation','main',2,'Lifetime Measurements','Lifetime sample preparation','Drop-cast hexane dispersions onto acetone-cleaned glass coverslips to make a rough film. This is not a separate synthesis recipe or a measured film thickness.','lifetime-acquisition',[],['G5'])
F('lifetime-excitation','main',2,'Lifetime Measurements','Lifetime excitation','Use PicoQuant LDH-P-C-405B pulsed excitation, wide-field illumination and neutral-density attenuation. The stated optical-power regime is several nW to hundreds of pW, not exact interval endpoints.','lifetime-acquisition',[Q('pulse duration','~70','ps'),Q('excitation wavelength','405','nm'),Q('low repetition rate','400','kHz'),Q('high repetition rate','2.5','MHz'),Q('spot diameter','~100','um'),Q('mean excitons per dot per pulse','~1e-5','dimensionless'),Q('optical power regime','several nW to hundreds of pW',None)],['G5'])
F('lifetime-detection','main',2,'Lifetime Measurements','Lifetime detection and fitting','Collect through a 100×, NA 1.3 oil-immersion objective, dichroic and long-pass filter; use Perkin-Elmer SPCM-AQR-14 SPAD and PicoQuant PicoHarp 300 TCSPC. Igor Pro fits triexponential histograms and computes the reported average lifetime from amplitude and lifetime coefficients.','lifetime-acquisition',[Q('objective magnification','100','fold'),Q('objective numerical aperture','1.3','dimensionless')],['G5'])
F('lifetime-table-contract','si',6,'Table S1 caption','Lifetime fit table meaning','The eighteen rows report mean fit coefficients and mean average lifetimes for four core sizes. Amplitude coefficients are normalized, but displayed rounding and averaging need not reproduce exact unity or exact average lifetime from the printed mean coefficients. Initial guesses strongly affect individual components, less the converged mean lifetime.','lifetime-table',[],['G8'])
F('lifetime-example','si',7,'Figure S7','Example lifetime trace','A film with 5.5 nm cores and 16.9 CdS monolayers is excited at 405 nm and 1.0 MHz, detected with SPAD/TCSPC and fitted triexponentially. Its shell count is not identified with Table S1’s 15.57 ML large-core row.','si-large-core-example',[Q('core diameter','5.5','nm'),Q('shell thickness','16.9','monolayer'),Q('excitation wavelength','405','nm'),Q('repetition rate','1.0','MHz')],['C6','G3'])
F('blinking-examples','si',8,'Figure S8 caption continued S9','Individual blinking examples','The upper binary panel is 2.2 nm core/14.5 ML CdS; the lower panel is 5.5 nm core/16.9 ML CdS. Yellow means on and black off. The lower line traces each use dot index 6 from different populations, not one shared specimen.','si-blinking-examples',[Q('small core diameter','2.2','nm'),Q('small core shell thickness','14.5','monolayer'),Q('large core diameter','5.5','nm'),Q('large core shell thickness','16.9','monolayer'),Q('integration time','100','ms')],['C6','G3'])
F('blinking-examples-threshold','si',9,'Figure S8 continuation','Example trace threshold','The SI states 91 ms readout and about 45 dots per panel. Line traces subtract T=B+2 sqrt(B), so plotted zero is threshold, unlike the unsubtracted I_pix used to define classification. Both selected dot indices equal 6 but belong to different populations.','si-blinking-examples',[Q('readout time','91','ms'),Q('displayed dots per panel','~45','count'),Q('selected index in each population','6','identifier')])
F('secondary-thin-ftir','si',5,'Figure S6 caption','Thin/thick secondary-amine signatures','The caption identifies synthesis using secondary dioctylamine but calls the thin-shell ligand oleylamine with an NH2 band. Preserve that unresolved identity inconsistency and the printed peak assignments, rather than changing the chemistry to match an interpretation.','si-secondary-ftir',[Q('thin-shell count','5','monolayer'),Q('thick-shell count','11','monolayer'),Q('caption NH2 bend','~1653','cm^-1'),Q('thin oleate asymmetric','1542','cm^-1'),Q('thin oleate symmetric','1469','cm^-1'),Q('thick oleate asymmetric','1542','cm^-1'),Q('thick oleate symmetric','1429','cm^-1')],['C3','G7'])
F('oa-morphology-pair','si',3,'Figure S3','OA-ratio morphology comparison','The left 1:4 Cd:OA particles are less obviously hexagonally faceted than the right 1:10 particles. Both bars are 10 nm. Core size and exact shell count are not identified.','si-oa-comparison',[Q('left Cd:OA','1:4','ratio_parts'),Q('right Cd:OA','1:10','ratio_parts'),Q('both scale bars','10','nm')],['G3'])
F('core-only-model','si',9,'Discussion','Hypothetical core-only threshold','The authors estimate that reaching 750 nm³ without a shell would require about 11.2 nm CdSe, described as roughly twice the CdSe Bohr radius and weakly or no longer confined. This is a hypothetical size argument, not a synthesized 11.2 nm specimen.','author-core-only-model',[Q('hypothetical volume','750','nm^3'),Q('hypothetical diameter','~11.2','nm'),Q('stated Bohr-radius size multiple','~2','fold')],['G6'],kind='author_model')
F('core-only-control','si',9,'Discussion','Seven-nanometer core-only control','A 7 nm CdSe core-only sample has about 15% ensemble QY at 680 nm before washing. Washing makes it essentially nonemissive; even the diluted unwashed sample is not visible at single-dot level on a slide. Its synthesis method is not reported and must not be borrowed from the 5.5 nm procedure.','core-only-7nm',[Q('core diameter','7','nm'),Q('unwashed ensemble QY','~15','%'),Q('emission wavelength','680','nm')],['G2','G3'])
F('larger-core-context','si',9,'Discussion final note','Larger-core historical failures','The authors mention still larger cores prepared previously for other purposes with QYs significantly below 15% and no visible UV-lamp luminescence. Sizes and synthesis conditions are absent; this remains contextual negative evidence.','other-large-core-context',[Q('qualitative QY ceiling','<15','%')],['G2','G3'])
F('lattice-background','main',1,'Introduction','Cited lattice-mismatch context','The introduction cites 3.9% CdSe/CdS lattice mismatch. Main p.2 separately calls CdSe/ZnS a large lattice match of 12%; the latter wording is preserved as background and not repaired or assigned to these CdS products.','cited-lattice-context',[Q('cited CdSe/CdS mismatch','3.9','%'),Q('cited CdSe/ZnS value on main p.2','12','%')],['G6'],kind='cited_context')
F('historical-blinking','main',4,'Anneal discussion','Historical versus present fractions','Prior cited work is described as progressing from 20% to 50% nonblinking fractions, while this study reports more than 85%. Do not treat prior fractions as new recipe outcome rows.','cited-prior-gNQD',[Q('earlier cited nonblinking fraction','20','%'),Q('later cited nonblinking fraction','50','%'),Q('current reported fraction','>85','%')],['G3'],kind='cited_context')
F('ftir-windows','main',5,'Figure 1 caption','FTIR plotted windows','Full spectra span 3500–1000 cm−1; characteristic alkyl stretches appear at 2950–2850 cm−1. Panels d–f show the 1700–1300 cm−1 ligand-signature region.','ftir-comparison',[Q('full spectrum interval','1000-3500','cm^-1'),Q('alkyl stretch interval','2850-2950','cm^-1'),Q('signature interval','1300-1700','cm^-1')])

